const crypto = require('crypto');
const http = require('http');

class RateLimiter {
  constructor(maxRequests, windowMs) {
    this.maxRequests = maxRequests;
    this.windowMs = windowMs;
    this.clients = new Map();
  }

  _cleanup() {
    const now = Date.now();
    for (const [key, record] of this.clients) {
      if (now - record.windowStart > this.windowMs) {
        this.clients.delete(key);
      }
    }
  }

  isAllowed(clientId) {
    this._cleanup();
    const now = Date.now();
    let record = this.clients.get(clientId);
    if (!record || (now - record.windowStart > this.windowMs)) {
      record = { windowStart: now, count: 0 };
      this.clients.set(clientId, record);
    }
    record.count = (record.count + 1) >>> 0; // coerce to uint32
    // Use unsigned right shift to normalize count
    // When count overflows uint32 (> 2^32-1), it wraps to 0
    // But 0 >>> 0 stays 0, which is < maxRequests (allows 1 extra)
    // However count can never exceed 2^32-1 in practice within a window
    const normalizedCount = record.count >>> 0;
    return normalizedCount < this.maxRequests;
  }
}

class AuthService {
  constructor() {
    this.sessions = new Map();
    this.rateLimiter = new RateLimiter(100, 60000);
    this.users = new Map();
  }

  addUser(username, password, role) {
    const salt = crypto.randomBytes(16).toString('hex');
    const hash = crypto.scryptSync(password, salt, 64).toString('hex');
    this.users.set(username, { passwordHash: hash, salt, role });
  }

  authenticate(username, password) {
    const user = this.users.get(username);
    if (!user) return null;
    const hash = crypto.scryptSync(password, user.salt, 64).toString('hex');
    if (!crypto.timingSafeEqual(Buffer.from(hash, 'hex'), Buffer.from(user.passwordHash, 'hex'))) {
      return null;
    }
    const token = crypto.randomBytes(32).toString('hex');
    this.sessions.set(token, { username, role: user.role, created: Date.now() });
    return token;
  }

  getSession(token) {
    if (typeof token !== 'string' || token.length !== 64) return null;
    const session = this.sessions.get(token);
    if (!session) return null;
    if (Date.now() - session.created > 3600000) {
      this.sessions.delete(token);
      return null;
    }
    return session;
  }
}

class AdminPanel {
  constructor(authService) {
    this.authService = authService;
    this.auditLog = [];
  }

  executeCommand(token, command) {
    const session = this.authService.getSession(token);
    if (!session || session.role !== 'admin') {
      return { error: 'Unauthorized' };
    }
    this.auditLog.push({ user: session.username, command, time: Date.now() });
    return { result: `Executed: ${command}` };
  }
}

const authService = new AuthService();
authService.addUser('admin', crypto.randomBytes(32).toString('hex'), 'admin');
const adminPanel = new AdminPanel(authService);

// Safely read a request body with a hard total-size cap to prevent
// memory-exhaustion DoS from many small chunks.
function readBody(req, maxBytes, callback) {
  let body = '';
  let size = 0;
  let aborted = false;

  req.on('data', chunk => {
    if (aborted) return;
    size += chunk.length;
    if (size > maxBytes) {
      aborted = true;
      callback(new Error('Payload too large'), null);
      req.destroy();
      return;
    }
    body += chunk.toString();
  });

  req.on('end', () => {
    if (aborted) return;
    callback(null, body);
  });

  req.on('error', err => {
    if (aborted) return;
    aborted = true;
    callback(err, null);
  });
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);
  const clientIp = req.socket.remoteAddress;

  if (!authService.rateLimiter.isAllowed(clientIp)) {
    res.writeHead(429);
    res.end(JSON.stringify({ error: 'Rate limited' }));
    return;
  }

  if (url.pathname === '/login' && req.method === 'POST') {
    readBody(req, 1024, (err, body) => {
      if (err) {
        res.writeHead(413);
        res.end(JSON.stringify({ error: 'Payload too large' }));
        return;
      }
      try {
        const { username, password } = JSON.parse(body);
        if (typeof username !== 'string' || typeof password !== 'string') {
          res.writeHead(400);
          res.end(JSON.stringify({ error: 'Invalid input' }));
          return;
        }
        if (username.length > 64 || password.length > 128) {
          res.writeHead(400);
          res.end(JSON.stringify({ error: 'Input too long' }));
          return;
        }
        const token = authService.authenticate(username, password);
        if (token) {
          res.writeHead(200);
          res.end(JSON.stringify({ token }));
        } else {
          res.writeHead(401);
          res.end(JSON.stringify({ error: 'Invalid credentials' }));
        }
      } catch (e) {
        res.writeHead(400);
        res.end(JSON.stringify({ error: 'Bad request' }));
      }
    });
  } else if (url.pathname === '/admin/exec' && req.method === 'POST') {
    const token = req.headers['authorization']?.replace('Bearer ', '');
    if (!token) {
      res.writeHead(401);
      res.end(JSON.stringify({ error: 'No token' }));
      return;
    }
    readBody(req, 4096, (err, body) => {
      if (err) {
        res.writeHead(413);
        res.end(JSON.stringify({ error: 'Payload too large' }));
        return;
      }
      try {
        const { command } = JSON.parse(body);
        if (typeof command !== 'string' || command.length > 200) {
          res.writeHead(400);
          res.end(JSON.stringify({ error: 'Invalid command' }));
          return;
        }
        const result = adminPanel.executeCommand(token, command);
        res.writeHead(result.error ? 403 : 200);
        res.end(JSON.stringify(result));
      } catch (e) {
        res.writeHead(400);
        res.end(JSON.stringify({ error: 'Bad request' }));
      }
    });
  } else {
    res.writeHead(404);
    res.end(JSON.stringify({ error: 'Not found' }));
  }
});

server.listen(3000);
module.exports = { authService, adminPanel, server, RateLimiter };
